import sys
import json
from pathlib import Path

# Stubs as before
class Zephyr2AdaptiveSamplerV3:
    def suggest(self, obs):
        return 0.5

class Zephyr2AdaptiveSamplerV4(Zephyr2AdaptiveSamplerV3):
    def suggest(self, obs):
        return (obs.get('rel_variance', 0) + obs.get('coverage', 0) + obs.get('delta_coverage', 0)) / 3

class AdaptiveStationV02:
    def __init__(self):
        self.sampler = Zephyr2AdaptiveSamplerV4()

    def suggest(self, obs):
        p_base = self.sampler.suggest(obs)
        token_factor = max(0.5, obs.get('token_remaining_pct', 0.5) ** 0.5)  # Adjusted: square root for less aggressive boost
        return p_base * (1 - obs.get('token_var', 0) * 0.5) * token_factor  # Milder var penalty

    def prioritize(self, agents):
        sample_metrics = {
            a: {'rel_variance': 0.1, 'coverage': 0.9, 'delta_coverage': 0.05, 
                'token_var': 0.2, 'token_remaining_pct': 0.7} for a in agents
        }
        return {agent: self.suggest(metrics) for agent, metrics in sample_metrics.items()}

tasks = [
    {'task': 'Plan', 'agent': 'Nexus I', 'token_cost': 200},
    {'task': 'Build', 'agent': 'Axiom I', 'token_cost': 600},
    {'task': 'Document', 'agent': 'Logos I', 'token_cost': 400},
    {'task': 'Review UX', 'agent': 'Explorer I', 'token_cost': 300},
    {'task': 'Optimize', 'agent': 'Zephyr II', 'token_cost': 500}
]

station = AdaptiveStationV02()
priorities = station.prioritize([t['agent'] for t in tasks])

base_total = sum(t['token_cost'] for t in tasks) / 0.5

v02_total = 0
results = []
for t in sorted(tasks, key=lambda x: -priorities.get(x['agent'], 0.5)):
    time = t['token_cost'] / priorities.get(t['agent'], 0.5)
    v02_total += time
    results.append({'task': t['task'], 'agent': t['agent'], 'p': priorities.get(t['agent']), 'time': time})

out = {'base_total': base_total, 'v02_total': v02_total, 'delta': base_total - v02_total, 'results': results}
out_path = Path("storage/shared/meta/priorities/AS_v02_refined_pilot.json")
out_path.write_text(json.dumps(out, indent=2), encoding="utf-8")

print("Refined v0.2 test complete:", out)
